code_string = """from qiskit import transpile
from scipy.optimize import minimize

def run_and_analyze(circuit, aer_sim, graph):
    transpiled = transpile(circuit, aer_sim)
    params = list(transpiled.parameters)
    num_params = len(params)

    initial_params = [1.0] * num_params

    def objective(x):
        binds = {params[i]: [x[i]] for i in range(num_params)}
        job = aer_sim.run(transpiled, parameter_binds=[binds], shots=2048)
        counts = job.result().get_counts()
        return compute_expectation(counts, graph)

    result = minimize(objective, initial_params, method='COBYLA', options={'maxiter': 200})

    optimal = result.x
    binds = {params[i]: [optimal[i]] for i in range(num_params)}
    job = aer_sim.run(transpiled, parameter_binds=[binds], shots=8192)
    counts = job.result().get_counts()

    sorted_counts = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)
    top_two = [sorted_counts[0][0], sorted_counts[1][0]]
    return top_two
"""

